function defaultsFor(index: number) {
  if (index < 14) {
    return {
      priority: "Critical" as const,
      editorialStatus: "Published" as const,
      storyStatus: "Published" as const,
      galleryStatus: "Published" as const,
      customerExperienceStatus: "Ready" as const,
    };
  }

  if (index < 32) {
    return {
      priority: "High" as const,
      editorialStatus: "Ready" as const,
      storyStatus: "Ready" as const,
      galleryStatus: "Ready" as const,
      customerExperienceStatus: "In Progress" as const,
    };
  }

  if (index < 62) {
    return {
      priority: "High" as const,
      editorialStatus: "Interview" as const,
      storyStatus: "In Progress" as const,
      galleryStatus: "In Progress" as const,
      customerExperienceStatus: "Not Started" as const,
    };
  }

  return {
    priority: "Medium" as const,
    editorialStatus: "Research" as const,
    storyStatus: "Not Started" as const,
    galleryStatus: "Not Started" as const,
    customerExperienceStatus: "Not Started" as const,
  };
}

export const vermont100Makers: Vermont100Maker[] = seeds.slice(0, 100).map((seed, index) => {
  const id = `vermont-100-maker-${String(index + 1).padStart(3, "0")}`;
  const slug = slugify(seed.makerName);
  const defaultStatus = defaultsFor(index);

  return {
    id,
    slug,
    makerName: seed.makerName,
    studio: seed.studio ?? "",
    town: seed.town ?? "",
    region: seed.region ?? "",
    craft: seed.craft,
    category: seed.category,
    priority: seed.priority ?? defaultStatus.priority,
    editorialStatus: seed.editorialStatus ?? defaultStatus.editorialStatus,
    storyStatus: seed.storyStatus ?? defaultStatus.storyStatus,
    galleryStatus: seed.galleryStatus ?? defaultStatus.galleryStatus,
    customerExperienceStatus: seed.customerExperienceStatus ?? defaultStatus.customerExperienceStatus,
    collections: seed.collections ?? [],
    giftGuides: seed.giftGuides ?? [],
    workshop: seed.workshop ?? false,
    ships: seed.ships ?? false,
    customOrders: seed.customOrders ?? seed.craft.toLowerCase().includes("custom"),
    onlineStore: seed.onlineStore ?? false,
    studioVisits: seed.studioVisits ?? false,
    yearsCrafting: seed.yearsCrafting ?? null,
    website: seed.website ?? KNOWN_MAKER_WEBSITES[seed.makerName] ?? "",
    contactEmail: seed.contactEmail ?? "",
  };
});
